describe('Save Search Query Feature', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should successfully save a search query and display saved queries list', () => {
    // Intercept the API call to save the search
    cy.intercept('POST', '/api/search/save').as('saveSearch');

    // Find and fill search input
    cy.get('[data-testid="search-input"]').type('Cypress automation');

    // Find and click save button
    cy.get('[data-testid="save-search-btn"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Search saved successfully');

    // Verify search query is stored
    cy.get('[data-testid="saved-searches-list"]').should('be.visible');
    cy.get('[data-testid="saved-search-item"]').should('contain', 'Cypress automation');

    // Verify saved search item has a delete button
    cy.get('[data-testid="saved-search-item"]').first().should('have.css', 'button', {
      'display': 'block',
      'data-testid': 'delete-saved-search-btn'
    });

    // Verify search query appears in saved searches list
    cy.get('[data-testid="saved-search-item"]').first().should('contain', 'Cypress automation');
  });

  it('should handle edge case: saving an empty search query', () => {
    // Intercept the API call to save the search
    cy.intercept('POST', '/api/search/save').as('saveSearch');

    // Find and clear search input
    cy.get('[data-testid="search-input"]').clear();

    // Find and click save button
    cy.get('[data-testid="save-search-btn"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Search saved successfully');

    // Verify empty search is not stored
    cy.get('[data-testid="saved-searches-list"]').should('be.visible');
    cy.get('[data-testid="saved-search-item"]').should('not.exist');

    // Verify no empty search items are displayed
    cy.get('[data-testid="saved-search-item"]').should('not.exist');
  });
});
